1	package edgefleet
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"io"
8		"strings"
9		"testing"
10	)
11	
12	// errOnlyWriter rejects every write with err, accepting no bytes.
13	type errOnlyWriter struct{ err error }
14	
15	func (w *errOnlyWriter) Write(p []byte) (int, error) { return 0, w.err }
16	
17	// prefixErrWriter accepts up to prefix bytes of one write, then errors,
18	// keeping the accepted prefix so callers can inspect what landed.
19	type prefixErrWriter struct {
20		prefix int
21		err    error
22		got    bytes.Buffer
23	}
24	
25	func (w *prefixErrWriter) Write(p []byte) (int, error) {
26		k := w.prefix
27		if k > len(p) {
28			k = len(p)
29		}
30		if k > 0 {
31			w.got.Write(p[:k])
32		}
33		if k < len(p) {
34			return k, w.err
35		}
36		return k, nil
37	}
38	
39	// shortWriter always accepts at most accept bytes and never errors.
40	type shortWriter struct {
41		accept int
42		calls  int
43		got    bytes.Buffer
44	}
45	
46	func (w *shortWriter) Write(p []byte) (int, error) {
47		w.calls++
48		k := w.accept
49		if k > len(p) {
50			k = len(p)
51		}
52		if k > 0 {
53			w.got.Write(p[:k])
54		}
55		return k, nil
56	}
57	
58	// failOnCallWriter succeeds (buffering) until its failAt-th call, then
59	// errors; it counts every attempted write.
60	type failOnCallWriter struct {
61		calls  int
62		failAt int
63		err    error
64		got    bytes.Buffer
65	}
66	
67	func (w *failOnCallWriter) Write(p []byte) (int, error) {
68		w.calls++
69		if w.calls == w.failAt {
70			return 0, w.err
71		}
72		return w.got.Write(p)
73	}
74	
75	var errSentinelOutput = errors.New("synthetic output device failure")
76	
77	// closingInput builds an input whose last line closes exactly one window
78	// [wantStart,wantEnd) for key "k", using one of the four entry shapes.
79	type outputFixture struct {
80		name      string
81		run       func(r io.Reader, out, late io.Writer) error
82		input     string
83		wantStart int64
84		wantEnd   int64
85		closeLine int // physical line that triggers the window output
86	}
87	
88	func outputFixtures() []outputFixture {
89		fixed := strings.Join([]string{
90			`{"type":"event","key":"k","time":500,"value":7}`, // line 1
91			`{"type":"watermark","time":1000}`,                // line 2 closes [0,1000)
92		}, "\n")
93		sliding := strings.Join([]string{
94			`{"type":"event","key":"k","time":700,"value":7}`, // [0,1000),[500,1500)
95			`{"type":"watermark","time":1000}`,                // line 2 closes only [0,1000)
96		}, "\n")
97		partitioned := strings.Join([]string{
98			`{"type":"event","key":"k","time":500,"value":7,"partition":0}`,
99			`{"type":"watermark","time":1000,"partition":1}`, // p1 reports
100			`{"type":"watermark","time":1000,"partition":0}`, // line 3: effective 1000, closes
101		}, "\n")
102		idleDriven := strings.Join([]string{
103			`{"type":"event","key":"k","time":500,"value":7,"partition":0}`,
104			`{"type":"watermark","time":1000,"partition":0}`,
105			`{"type":"idle","partition":1}`, // line 3: p1 idle lets effective reach 1000
106		}, "\n")
107		return []outputFixture{
108			{
109				name:      "fixed",
110				run:       func(r io.Reader, out, late io.Writer) error { return RunAggregate(r, 1000, out, late) },
111				input:     fixed,
112				wantStart: 0,
113				wantEnd:   1000,
114				closeLine: 2,
115			},
116			{
117				name: "sliding",
118				run: func(r io.Reader, out, late io.Writer) error {
119					return RunAggregateSliding(r, 1000, 500, out, late)
120				},
121				input:     sliding,
122				wantStart: 0,
123				wantEnd:   1000,
124				closeLine: 2,
125			},
126			{
127				name: "partitioned",
128				run: func(r io.Reader, out, late io.Writer) error {
129					return RunAggregatePartitioned(r, 1000, 2, out, late)
130				},
131				input:     partitioned,
132				wantStart: 0,
133				wantEnd:   1000,
134				closeLine: 3,
135			},
136			{
137				name: "idle-driven",
138				run: func(r io.Reader, out, late io.Writer) error {
139					return RunAggregatePartitionedSliding(r, 1000, 1000, 2, out, late)
140				},
141				input:     idleDriven,
142				wantStart: 0,
143				wantEnd:   1000,
144				closeLine: 3,
145			},
146		}
147	}
148	
149	func TestWindowResultWriteErrorFails(t *testing.T) {
150		for _, fx := range outputFixtures() {
151			t.Run(fx.name, func(t *testing.T) {
152				out := &errOnlyWriter{err: errSentinelOutput}
153				err := fx.run(strings.NewReader(fx.input), out, &bytes.Buffer{})
154				var oe *OutputError
155				if !errors.As(err, &oe) {
156					t.Fatalf("expected *OutputError, got %T: %v", err, err)
157				}
158				if oe.Line != fx.closeLine {
159					t.Errorf("Line = %d, want %d", oe.Line, fx.closeLine)
160				}
161				if oe.Kind != "window result" {
162					t.Errorf("Kind = %q, want %q", oe.Kind, "window result")
163				}
164				wantDetail := fmt.Sprintf("key %q window [%d,%d)", "k", fx.wantStart, fx.wantEnd)
165				if !strings.Contains(err.Error(), wantDetail) {
166					t.Errorf("error %q must identify %s", err.Error(), wantDetail)
167				}
168				if !errors.Is(err, errSentinelOutput) {
169					t.Errorf("errors.Is must expose the writer's original error, got %v", err)
170				}
171			})
172		}
173	}
174	
175	func TestWindowResultPrefixThenErrorFails(t *testing.T) {
176		for _, fx := range outputFixtures() {
177			t.Run(fx.name, func(t *testing.T) {
178				out := &prefixErrWriter{prefix: 3, err: errSentinelOutput}
179				err := fx.run(strings.NewReader(fx.input), out, &bytes.Buffer{})
180				var oe *OutputError
181				if !errors.As(err, &oe) {
182					t.Fatalf("expected *OutputError, got %T: %v", err, err)
183				}
184				if oe.Kind != "window result" || oe.Line != fx.closeLine {
185					t.Errorf("got Kind=%q Line=%d, want window result at line %d", oe.Kind, oe.Line, fx.closeLine)
186				}
187				if !errors.Is(err, errSentinelOutput) {
188					t.Errorf("errors.Is must expose the writer's error after a prefix, got %v", err)
189				}
190				if out.got.Len() != 3 {
191					t.Errorf("accepted prefix must remain in the writer, got %q", out.got.String())
192				}
193			})
194		}
195	}
196	
197	func TestWindowResultShortWriteWithoutErrorFails(t *testing.T) {
198		for _, accept := range []int{0, 1, 4} {
199			for _, fx := range outputFixtures() {
200				t.Run(fmt.Sprintf("%s/accept%d", fx.name, accept), func(t *testing.T) {
201					out := &shortWriter{accept: accept}
202					err := fx.run(strings.NewReader(fx.input), out, &bytes.Buffer{})
203					var oe *OutputError
204					if !errors.As(err, &oe) {
205						t.Fatalf("expected *OutputError for a nil-error short write, got %T: %v", err, err)
206					}
207					if !errors.Is(err, io.ErrShortWrite) {
208						t.Errorf("short write must be errors.Is io.ErrShortWrite, got %v", err)
209					}
210					if oe.Kind != "window result" || oe.Line != fx.closeLine {
211						t.Errorf("got Kind=%q Line=%d, want window result at line %d", oe.Kind, oe.Line, fx.closeLine)
212					}
213					wantDetail := fmt.Sprintf("key %q window [%d,%d)", "k", fx.wantStart, fx.wantEnd)
214					if !strings.Contains(err.Error(), wantDetail) {
215						t.Errorf("error %q must identify %s", err.Error(), wantDetail)
216					}
217				})
218			}
219		}
220	}
221	
