func (r *chunkReader) Read(p []byte) (int, error) {
	if r.pos >= len(r.data) {
		return 0, io.EOF
	}
	var end int
	if len(r.cuts) > 0 {
		end = r.cuts[0]
		r.cuts = r.cuts[1:]
		if end > len(r.data) {
			end = len(r.data)
		}
	} else {
		end = len(r.data)
	}
	if end <= r.pos { // defensive: a non-advancing cut would loop forever
		end = r.pos + 1
	}
	n := copy(p, r.data[r.pos:end])
	r.pos += n
	if n < end-(r.pos-n) {
		// The caller's buffer was smaller than the requested chunk; report the
		// short read honestly instead of silently merging it with the next.
		return n, nil
	}
	if r.pos >= len(r.data) {
		return n, io.EOF
	}
	return n, nil
}

