// sizes), then, only after `complete` whole records plus their trailing
// newline have been delivered, every further Read fails with readErr. The
// incomplete tail following the error is never delivered.
type failingAfterReader struct {
	data     []byte
	pos      int
	failAt   int // byte offset from which reads fail
	err      error
	failSize int // size to report alongside the error on the failing call
}

var errSentinelChunkedRead = errors.New("synthetic upstream read failure")

func (r *failingAfterReader) Read(p []byte) (int, error) {
	if r.pos >= r.failAt {
		return 0, r.err
	}
	end := r.pos + len(p)
	if end > r.failAt {
		end = r.failAt
	}
	n := copy(p, r.data[r.pos:end])
	r.pos += n
	if r.pos >= r.failAt {
		return n, r.err // last good bytes and the failure in one Read, as net.Conn may
	}
	return n, nil
}

