	for {
		n, rerr := r.Read(chunkBuf)
		piece := chunkBuf[:n]
		for len(piece) > 0 {
			i := bytes.IndexByte(piece, '\n')
			var raw []byte
			if i < 0 {
				raw, piece = piece, nil
			} else {
				raw, piece = piece[:i], piece[i+1:]
			}
			lineNo++
			line := strings.TrimSuffix(string(raw), "\r")
			if strings.TrimSpace(line) == "" {
				continue
			}
			if err := s.processLine(line, lineNo); err != nil {
				return err
			}
		}
		if rerr != nil {
			if rerr == io.EOF {
				return nil
			}
			return rerr
		}
	}
}

