476			// One read returns line 5's trailing newline together with the error,
477			// as a net.Conn may. The complete record still counts; the error wins.
478			check(t, &failingAfterReader{data: []byte(full), failAt: goodBoundary, err: errSentinelChunkedRead, errOnBoundary: true})
479		})
480		t.Run("one byte per read before failure", func(t *testing.T) {
481			// Fragmented delivery up to the boundary, last byte plus error; the
482			// result must be identical to a large-buffer read.
483			check(t, &failingAfterReader{data: []byte(full), failAt: goodBoundary, err: errSentinelChunkedRead, chunk: 1, errOnBoundary: true})
484		})
485	}
486	
487	// TestChunkedArrivalDiscriminatesCorrectAggregates ensures the invariant tests
488	// above would actually fail on the regressions they target: missed counts,
489	// double counting, and a late event admitted into the still-open overlap
490	// window all change the output even when the input is delivered one byte at a
491	// time. This is a characterization guard for the assertions used throughout
492	// the file (expected outputs are computed from the spec, not echoed back).
493	func TestChunkedArrivalDiscriminatesCorrectAggregates(t *testing.T) {
494		type window struct {
495			key        string
496			start, end int64
497			count      int64
498			sum        int64
499		}
500		correct := []window{
501			{"温度", 0, 1000, 1, 2},
502			{"温度", 600, 1600, 2, 5},
503		}
504		missedSecondEvent := []window{
505			{"温度", 0, 1000, 1, 2},
506			{"温度", 600, 1600, 1, 2}, // event time=1000 lost
507		}
508		doubleFirstEvent := []window{
509			{"温度", 0, 1000, 2, 4}, // time=700 counted twice
510			{"温度", 600, 1600, 3, 7},
511		}
512		lateAdmitted := []window{
513			{"温度", 0, 1000, 1, 2},
514			{"温度", 600, 1600, 3, 14}, // late time=999/value=9 wrongly added
515		}
516		render := func(ws []window) string {
517			var b strings.Builder
518			for _, w := range ws {
519				fmt.Fprintf(&b, `{"key":%q,"start":%d,"end":%d,"count":%d,"sum":%d}`+"\n", w.key, w.start, w.end, w.count, w.sum)
520			}
521			return b.String()
522		}
523		want := render(correct)
524		if want != canonicalChunkedWindows {
525			t.Fatalf("test harness render drifted from the pinned expectation:\n got: %q\nwant: %q", want, canonicalChunkedWindows)
526		}
527		for name, ws := range map[string][]window{
528			"missed event":  missedSecondEvent,
529			"double count":  doubleFirstEvent,
530			"late admitted": lateAdmitted,
531		} {
532			if got := render(ws); got == want {
533				t.Fatalf("mutated scenario %q unexpectedly matched the correct output", name)
534			}
535		}
536	
537		// End-to-end: deliver the real stream one byte at a time and confirm the
538		// late value 9 never appears in any aggregate sum.
539		out, _, err := func() (string, string, error) {
540			input := canonicalChunkedScenario()
541			cuts := make([]int, 0, len(input)-1)
542			for at := 1; at < len(input); at++ {
543				cuts = append(cuts, at)
544			}
545			return runChunked(t, input, cuts)
546		}()
547		if err != nil {
548			t.Fatalf("unexpected error: %v", err)
549		}
550		if strings.Contains(out, `"sum":14`) || strings.Contains(out, `"sum":9`) {
551			t.Fatalf("late event value leaked into a window: %q", out)
552		}
553	}
554	
555	// TestChunkedArrivalAcrossEntryPoints repeats the fragmentation invariant for
556	// the other public entry shapes, so read-batching can never become a record
557	// boundary in fixed/sliding/partitioned-only modes either.
558	func TestChunkedArrivalAcrossEntryPoints(t *testing.T) {
559		type fixture struct {
560			name string
561			run  func(io.Reader, io.Writer, io.Writer) error
562			in   string
563			want string
564		}
565		events := func(records ...string) string { return strings.Join(records, "\n") + "\n" }
566	
567		fixed := events(
568			`{"type":"event","key":"温度","time":100,"value":2}`,
569			`{"type":"event","key":"温度","time":200,"value":3}`,
570			`{"type":"watermark","time":1000}`,
571		)
572		sliding := events(
573			`{"type":"event","key":"温度","time":700,"value":2}`,
574			`{"type":"watermark","time":1000}`,
575		)
576		partitioned := events(
577			`{"type":"event","key":"温度","time":100,"value":2,"partition":0}`,
578			`{"type":"event","key":"温度","time":200,"value":3,"partition":1}`,
579			`{"type":"watermark","time":1000,"partition":0}`,
580			`{"type":"watermark","time":1000,"partition":1}`,
581		)
582		fxs := []fixture{
583			{"fixed", func(r io.Reader, o, l io.Writer) error { return RunAggregate(r, 1000, o, l) }, fixed,
584				`{"key":"温度","start":0,"end":1000,"count":2,"sum":5}` + "\n"},
585			{"sliding", func(r io.Reader, o, l io.Writer) error { return RunAggregateSliding(r, 1000, 600, o, l) }, sliding,
586				`{"key":"温度","start":0,"end":1000,"count":1,"sum":2}` + "\n"},
587			{"partitioned", func(r io.Reader, o, l io.Writer) error { return RunAggregatePartitioned(r, 1000, 2, o, l) }, partitioned,
588				`{"key":"温度","start":0,"end":1000,"count":2,"sum":5}` + "\n"},
589		}
590	
591		for _, fx := range fxs {
592			fx := fx
593			t.Run(fx.name, func(t *testing.T) {
594				// Reference one-shot result.
595				var refOut, refLate bytes.Buffer
596				if err := fx.run(strings.NewReader(fx.in), &refOut, &refLate); err != nil {
597					t.Fatalf("one-shot: unexpected error: %v", err)
598				}
599				if refOut.String() != fx.want {
600					t.Fatalf("one-shot output:\n got: %q\nwant: %q", refOut.String(), fx.want)
601				}
602				// Every two-read cut and several uniform sizes.
603				schedules := append(allCuts(len(fx.in)),
604					uniformCuts(len(fx.in), 1),
605					uniformCuts(len(fx.in), 3),
606					uniformCuts(len(fx.in), 7),
607				)
608				for _, cuts := range schedules {
609					var out, late bytes.Buffer
610					if err := fx.run(newChunkReader(fx.in, cuts...), &out, &late); err != nil {
611						t.Fatalf("cuts %v: unexpected error: %v", cuts, err)
612					}
613					if out.String() != refOut.String() {
614						t.Fatalf("cuts %v: window output:\n got: %q\nwant: %q", cuts, out.String(), refOut.String())
615					}
616					if late.String() != refLate.String() {
617						t.Fatalf("cuts %v: late output:\n got: %q\nwant: %q", cuts, late.String(), refLate.String())
618					}
619				}
620			})
621		}
622	}
